import javax.swing.*;import java.awt.*;
public class LibrarySearchScreen extends JFrame {
 JTextField query=new JTextField(18);JComboBox<String> category=new JComboBox<>(new String[]{"All","Book","Author","Subject"});DefaultListModel<String> model=new DefaultListModel<>();JLabel status=new JLabel("Ready");
 LibrarySearchScreen(){super("Campus Library Search");JLabel title=new JLabel("Campus Library",SwingConstants.CENTER);title.setFont(title.getFont().deriveFont(Font.BOLD,20f));JPanel search=new JPanel();search.add(query);search.add(category);JButton find=new JButton("Search");search.add(find);JPanel north=new JPanel(new BorderLayout());north.add(title,BorderLayout.NORTH);north.add(search,BorderLayout.SOUTH);add(north,BorderLayout.NORTH);model.addElement("Effective Java");model.addElement("Database System Concepts");model.addElement("Java: The Complete Reference");JList<String> list=new JList<>(model);add(new JScrollPane(list),BorderLayout.CENTER);JButton prev=new JButton("Prev"),next=new JButton("Next"),reserve=new JButton("Reserve");JPanel buttons=new JPanel();buttons.add(prev);buttons.add(next);buttons.add(reserve);JPanel south=new JPanel(new BorderLayout());south.add(buttons,BorderLayout.NORTH);south.add(status,BorderLayout.SOUTH);add(south,BorderLayout.SOUTH);find.addActionListener(e->status.setText("Search: "+query.getText()));reserve.addActionListener(e->status.setText("Selected: "+list.getSelectedValue()));setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(650,420);setMinimumSize(new Dimension(420,300));setLocationRelativeTo(null);}
 public static void main(String[] a){SwingUtilities.invokeLater(()->new LibrarySearchScreen().setVisible(true));}
}
